import os
import hashlib
from Crypto.PublicKey import RSA
from Crypto.Cipher import PKCS1_OAEP
from Crypto.Hash import SHA1, SHA256
from Crypto.Signature import pss

RSA_N_DEC = ""
RSA_E = 65537

RSA_P_DEC = ""
RSA_Q_DEC = ""

p = int(RSA_P_DEC)
q = int(RSA_Q_DEC)
n = p * q
phi = (p - 1) * (q - 1)
d = pow(RSA_E, -1, phi)

if n != int(RSA_N_DEC):
    print("Error: n != p*q. Check p and q values!")
    exit(1)

print("Key is consistent (n = p*q).")

def decrypt_rsa_oaep(ciphertext_bytes, private_key, hash_algo):
    mgf = lambda x, y: pss.MGF1(x, y, hash_algo)
    cipher = PKCS1_OAEP.new(private_key, hashAlgo=hash_algo, mgfunc=mgf)
    return cipher.decrypt(ciphertext_bytes)

def main():
    enc_path = "masterkey.enc"
    hash_path = "masterkey.sha256"

    if not os.path.exists(enc_path):
        print(f"File {enc_path} does not exist!")
        return
    if not os.path.exists(hash_path):
        print(f"File {hash_path} does not exist!")
        return

    with open(enc_path, "rb") as f:
        encrypted_data = f.read()
    with open(hash_path, "rb") as f:
        stored_hash = f.read()
        if len(stored_hash) != 32:
            print("Invalid hash size.")
            return

    print("Stored hash (hex):", stored_hash.hex())

    private_key = RSA.construct((n, RSA_E, d, p, q))

    decrypted_key = None
    for hash_algo in [SHA1, SHA256]:
        try:
            decrypted_key = decrypt_rsa_oaep(encrypted_data, private_key, hash_algo)
            print(f"Decryption succeeded with hash: {hash_algo.__name__}")
            break
        except ValueError as e:
            print(f"Decryption with {hash_algo.__name__} failed: {e}")
            continue

    if decrypted_key is None:
        print("Decryption failed with any hash.")
        return

    if len(decrypted_key) != 32:
        print(f"Decrypted key has length {len(decrypted_key)} bytes (expected 32).")
        return

    calculated_hash = hashlib.sha256(decrypted_key).digest()

    print("Calculated hash (hex):", calculated_hash.hex())
    print("Master key (hex):", decrypted_key.hex())

    if calculated_hash == stored_hash:
        print("✅ Hash matches! Key is correct.")
    else:
        print("❌ Hash does NOT match! Key is incorrect or data has been modified.")

if __name__ == "__main__":
    main()